#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    // vector 기본 사용법
    vector<int> scores = {85, 92, 78, 91, 88};

    // 접근 O(1)
    cout << scores[0] << endl;        // 85 (첫 번째)
    cout << scores.back() << endl;    // 88 (마지막)

    // 탐색 O(n)
    auto it = find(scores.begin(), scores.end(), 92);
    if (it != scores.end()) {
        cout << distance(scores.begin(), it) << endl; // 1
    }

    // 추가/삭제
    scores.push_back(95);             // 맨 뒤 추가 O(1)
    scores.insert(scores.begin() + 2, 99); // 중간 삽입 O(n)
    scores.pop_back();                // 맨 뒤 삭제 O(1)

    for (int score : scores) cout << score << " ";
    return 0;
}

