#include <stdio.h>
#include <stdlib.h>

int main() {
    // 정적 배열과 동적 배열 사용법
    int scores[5] = {85, 92, 78, 91, 88};
    int size = 5;

    // 접근 O(1)
    printf("%d\n", scores[0]);        // 85 (첫 번째)
    printf("%d\n", scores[size-1]);   // 88 (마지막)

    // 탐색 O(n)
    for (int i = 0; i < size; i++) {
        if (scores[i] == 92) {
            printf("Found at index: %d\n", i);
            break;
        }
    }

    // 동적 배열 예시
    int* dynamic_scores = malloc(6 * sizeof(int));
    for (int i = 0; i < 5; i++) dynamic_scores[i] = scores[i];
    dynamic_scores[5] = 95; // 맨 뒤 추가

    for (int i = 0; i < 6; i++) printf("%d ", dynamic_scores[i]);
    free(dynamic_scores);
    return 0;
}

