            Console.WriteLine(scores.IndexOf(92));  // 1
        }

        // 추가/삭제
        scores.Add(95);              // 맨 뒤 추가 O(1)
        scores.Insert(2, 99);        // 중간 삽입 O(n)
        scores.RemoveAt(scores.Count - 1); // 맨 뒤 삭제 O(1)

        Console.WriteLine(string.Join(", ", scores));
    }
}

