int main() {
    // vector의 동적 크기 변화 관찰
    vector<int> arr;
    for (int i = 0; i < 10; i++) {
        arr.push_back(i);
        cout << "Size: " << arr.size() 
             << ", Capacity: " << arr.capacity() << endl;
    }
    // 결과: capacity가 1→2→4→8→16... 순서로 2배씩 증가
    return 0;
}

