#include <stdio.h>
#include <stdlib.h>

// C에서 동적 배열 직접 구현
int main() {
    int capacity = 2;
    int size = 0;
    int* arr = malloc(capacity * sizeof(int));

    for (int i = 0; i < 10; i++) {
        // 리사이징 필요한지 확인
        if (size >= capacity) {
            capacity *= 2; // 2배로 증가
            arr = realloc(arr, capacity * sizeof(int));
            printf("리사이징! 새 capacity: %d\n", capacity);
        }

        arr[size++] = i;
        printf("Size: %d, Capacity: %d\n", size, capacity);
    }

    free(arr);
    return 0;
}

